package com.financecoach.service;
import com.financecoach.dto.*;import com.financecoach.entity.TransactionType;import com.financecoach.repository.TransactionRepository;import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.time.temporal.TemporalAdjusters;
@Service public class CoachService {private final TransactionRepository tx;public CoachService(TransactionRepository tx){this.tx=tx;}public SimulationResponse simulate(Long uid,SimulationRequest req){LocalDate n=LocalDate.now(),s=n.with(TemporalAdjusters.firstDayOfMonth()),e=n.with(TemporalAdjusters.lastDayOfMonth());BigDecimal income=n(tx.sumAmountByUserIdAndTypeAndDateBetween(uid,TransactionType.INCOME,s,e)),expense=n(tx.sumAmountByUserIdAndTypeAndDateBetween(uid,TransactionType.EXPENSE,s,e)),ni=income.add(req.getIncomeChange()),ne=expense.add(req.getExpenseChange()),net=ni.subtract(ne);SimulationResponse out=new SimulationResponse();out.setBaselineIncome(income);out.setBaselineExpenses(expense);out.setBaselineNetSavings(income.subtract(expense));out.setNewIncome(ni);out.setNewExpenses(ne);out.setNewNetSavings(net);out.setNewSavingsRate(ni.signum()==0?BigDecimal.ZERO:net.divide(ni,4,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)).setScale(2,RoundingMode.HALF_UP));return out;}public CoachResponse chat(Long uid,String question){String q=question==null?"":question.toLowerCase();if(q.contains("spend")||q.contains("highest")){return new CoachResponse("Review your monthly category report to identify the largest expense areas. I can only provide guidance from recorded transactions.");}if(q.contains("save")||q.contains("savings")){return new CoachResponse("Use the simulator to test income or expense changes, then compare the resulting savings rate before changing your plan.");}return new CoachResponse("I can help explain recorded spending, savings rates, goals, and what-if scenarios. Try asking where spending is highest or how to improve savings.");}private BigDecimal n(BigDecimal v){return v==null?BigDecimal.ZERO:v;}}
